import re
import sys

assignment = re.compile(
    r"\s*(a|b|TMP)\s*<-\s*"
    r"(?:([0-9]+)|\(\s*(a|b|TMP)\s*\+\s*([0-9]+)\s*\)\s*mod\s*100)"
    r"\s*;\s*"
)

values = {}

for line in sys.stdin:
    match = assignment.fullmatch(line)
    if match is None:
        continue

    target, constant, source, increment = match.groups()
    if constant is not None:
        values[target] = int(constant)
    else:
        values[target] = (values[source] + int(increment)) % 100

print(f"a ?= {values['a']}; b ?= {values['b']}; TMP ?= {values['TMP']};")
